#!/usr/bin/env python3
"""Freeze reviewer source-first answers. Reads answer-hidden packet only."""
import datetime,hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
P=ROOT/'audits/blind-W02-L09-review-copy.json'
b=json.loads(P.read_text());assert b['sourcePacketSha256']=='419d46ba692b1e45ad47174dcc8de9435085c2215512be60a5539b9658c78a95'
reasons={
299:["Speed is the norm of a velocity vector, so discards direction; the introduction explicitly distinguishes them.","The Euclidean norm is sqrt(3²+4²+0²)=5 m/s.","Velocity describes motion relative to an observer; a moving observer can obtain a different result, so the reference must be understood."],
300:["The derivative is the difference of the same B-coordinate function at two times, divided by elapsed time in the zero-interval limit.","A point rigidly attached to B has constant B coordinates. Its derivative relative to B is zero, although the rotating body can carry it around relative to A.","The old-tip to new-tip arrow in the fixed drawing is the actual small geometric displacement. It is not a change of the attached point's body-coordinate tuple."],
301:["Differentiation relative to an observer and representation in a coordinate basis are separate roles; changing the latter does not change which physical motion is measured.","The stated A-from-B rotation maps components by left multiplication R v_B. A free velocity vector does not acquire an origin translation when merely re-expressed.","The matrix's first column is (0,1,0), so twice that column is (0,2,0) m/s.","A linear rotation sends zero to zero. The nonzero A-relative motion comes from translation/rotation of B, not component re-expression alone."],
302:["The shorthand v_C denotes velocity of C's origin relative to the understood universal observer U.","The subscript identifies the moving origin C, the omitted reference is U, and leading A identifies expression coordinates."],
303:["Linear velocity is attached to a point and can differ between points; angular velocity characterizes rigid-body/frame rotation.","A nonzero angular-velocity vector specifies the instantaneous axis direction and angular speed as its norm.","Inner A is the relative observer, B the rotating frame, and outer C the component basis.","In the defined shorthand the physical observer is U. Leading A changes only the coordinates in which that angular velocity is written."],
305:["The drawing forms a chain from A origin to B origin to Q, requiring origin translation, a B-relative vector, and B-to-A orientation.","The B-relative vector must first be expressed in A: q_A=p_AB+R_AB q_B."],
306:["Differentiating p+Rq produces pdot+R qdot when Rdot=0. Constant relative orientation, not coincident origins, eliminates the rotational term.","Rz(90°) maps (2,0,0) to (0,2,0); adding origin velocity (1,0,0) yields (1,2,0).","Fixed in B gives qdot_B=0; constant R leaves only B-origin translation."],
309:["The right-hand rotational tangent velocity is omega cross r, not the reversed cross product or scalar dot product.","Projecting r perpendicular to the rotation axis gives radius |r|sin(theta).","Speed=2*3*sin(30°)=3 m/s.","(0,0,2) cross (3,0,0)=(0,6,0), following the right-hand rule.","An axis-aligned r is parallel to omega; their cross product is zero even for nonzero angular speed.","The finite chord is 2 rho sin(delta_angle/2), whereas arc is rho delta_angle. They agree to first order as the angle vanishes, giving exact instantaneous speed.","With coincident stationary origins the relative-motion term and rotational sweep remain: R v_relative+omega cross (R q_B). All vectors in the cross product must share the A basis."],
310:["The displayed boxes label origin translation, relative point motion expressed in A, and rotational sweep respectively.","R q_B=(0,2,0); R v_relative=(0,1,0); omega cross R q_B=(-4,0,0). Adding (1,0,0) yields (-3,1,0) m/s.","Body fixation eliminates relative point motion but not origin translation or rotational sweep.","At the origin r=0, so the rotational cross term is zero; specified zero relative motion leaves origin translation only."],
311:["The link-frame origin's linear velocity and link angular velocity are relative to base 0, not derivatives relative to the same moving link.","The summary explicitly propagates known base motion outward along links toward the end effector."],
312:["Vector components can be added only after their basis directions match; physically inherited and joint angular rates need a common expression frame.","Re-express inherited angular velocity with R, then add the new relative rate along child z: omega_child=R omega_parent+thetadot z_child.","The child z unit vector is (0,0,1), so its scaled components are (0,0,thetadot).","Opposite-direction coordinate rotations are inverses. Their product is identity, leaving the child-axis joint-rate vector.","Rx(90°) maps parent (0,0,2) to (0,-2,0); adding (0,0,3) gives (0,-2,3) rad/s."],
313:["The parent-fixed origin offset is swept by the parent's angular velocity omega_i. The new joint's axis passes through the child origin under the given placement.","Compute v_parent+omega_parent cross P in the parent basis, then rotate the entire sum into child coordinates.","The cross product is (0,6,0); adding (1,2,0) produces (1,8,0) m/s.","Rz(-90°) sends (x,y,z) to (y,-x,z), so (1,8,0) becomes (8,-1,0).","The child origin lies on the new revolute joint's own axis. Its own relative rotation adds angular rate but no translation of that point; downstream offset points can still move."],
314:["An ideal prismatic joint adds no relative angular rate, so only the rotated inherited omega remains.","The extension rate is along child z; add d_dot z_child after expressing inherited velocity in child coordinates.","Inherited velocity is (8,-1,0); adding extension velocity (0,0,4) gives (8,-1,4).","The coincident-origin zero-parent-linear-velocity premise removes the sweep and inherited translation. Angular rate remains (0,0,2); extension adds linear (0,0,3)."],
315:["Apply the multivariable chain rule: F_theta1 times theta1dot plus F_theta2 times theta2dot.","Rows index output coordinates and columns input joints, so the first row contains both partials of F and the second both partials of G.","F partials are (2q1,1)=(4,1); G partials are (q2,q1)=(3,2).","[[4,1],[3,2]] times (0.5,-1)=(1,-0.5) per second.","The differential is a local first-order linearization, not the exact finite displacement of a generic nonlinear map. Along a differentiable trajectory the instantaneous chain-rule velocity equality is exact."],
316:["At fixed q, J is a fixed linear operator on joint rates. The forward position map may still be nonlinear in q.","Configuration dependence can induce time dependence via q(t), but neither every trajectory nor every kinematic model requires changing J.","Six output twist components require six rows; n independent joint rates require n columns.","Matrix dimensions are (6 by 7)*(7 by 1)=(6 by 1).","The task has two output coordinates and three input joint coordinates, giving two rows and three columns."],
317:["The source stacks linear x/y/z velocity components over angular x/y/z velocity components, not positions or forces.","Being square is necessary for an ordinary inverse but not sufficient; rank must equal six at that configuration."],
318:["Both linear and angular free vectors rotate with the same R for the same observer and physical point, giving block diagonal (R,R).","The output components change, so left-multiply J by the six-dimensional output basis map. Right multiplication would instead change the input representation.","Rz(90°)(1,0,0)=(0,1,0); Rz(90°)(0,1,0)=(-1,0,0).","An invertible block rotation has an inverse, so multiplication cannot change the column-space dimension or repair rank loss.","Changing the tracked point on a rotating body changes linear velocity by omega cross the point offset. A pure basis change does not contain this physical point-shift effect."],
319:["The ordinary inverse solution is valid only for a nonsingular square J at the given configuration.","For the specified modeled task, singularity is a rank drop below attainable regular rank, reducing independent instantaneous task directions without removing mechanical joints.","A lost output direction need not align with a named coordinate axis. Rotating the basis preserves rank while changing its components.","The inverse is diag(1,1/epsilon), giving (0,1/epsilon); the second rate diverges as positive epsilon tends to zero.","J(qdot1,qdot2)=(qdot1,0). Target (2,0) admits (2,t) for any finite t; target (0,1) is outside the image and impossible exactly.","Divergence of inverse commands while approaching a singularity is different from solving a singular system. Compatible targets may have finite solutions and incompatible targets have none.","The source lists joint-axis alignment in the interior and workspace-edge configurations as examples, not as universal sufficient tests.","For the explicitly linear Cartesian map, the derivative is identity even at a limit-defined corner. Joint limits constrain admissible increments, but do not change the map's rank. This is a generated counterexample to treating all boundaries as rank singularities.","Columns one and three are independent standard basis vectors, so row rank is two despite repeated columns. Repetition alone does not remove either task direction.","The modeled differential task singularity is rank loss. Other failures such as collision, model mismatch or distinct singularity notions require their own definition and tests; a Jacobian does not certify all physical behavior."],
321:["RMRC maps desired Cartesian velocities into joint velocities in real time.","Forward Euler adds rate times elapsed time to the position state: q_next=q+qdot*dt. Source extraction contains a combining overdot although the preview renders it poorly; dimensional consistency and the velocity-control context agree.","Inverse J yields rates (0.2,-0.2); multiplying by 0.1 gives (0.02,-0.02); adding (1,2) yields (1.02,1.98).","The configuration evolves as rates are integrated, and the local Jacobian generally changes with it; the number of joints need not change.","The source lists singularity issues, long-trajectory drift and reliance on an accurate kinematic model.","An explicit Jacobian exposes the local mapping but cannot alone guarantee collision avoidance, bounded commands or valid physical predictions. Safety requires constraints and validation beyond the matrix.","The slide proposes that deep-RL behavior can resemble RMRC; this does not require every learned policy to compute an analytic inverse or eliminate singularities.","The printed source explicitly attributes RMRC to Whitney, 1969. This is source recall, not independently established historical priority."],
322:["The first comparison row contrasts analytic DH-based construction with data-driven online estimation.","The online-estimation examples are Broyden and neural networks, both printed in the table. Pagination and font changes are unrelated.","The traditional column lists RMRC, operational-space control and impedance control.","An exact derivative of a model remains subject to whether that model represents the physical robot accurately; analytic calculation does not cancel calibration errors.","Null-space rates satisfy J z=0, allowing redundancy resolution without adding primary instantaneous task velocity.","[1,1]*(1,-1)=0; each other listed vector produces a nonzero scalar.","The industrial-arm names printed are KUKA, ABB and UR.","The sim-to-real row associates Jacobian structure with bridging domain adaptation rather than assuming identical physical behavior.","The table gives a neural network as a learned replacement for explicit pseudoinverse computation, without claiming universal reachability or exactness.","Differentiable robotics backpropagates through kinematics, using the derivative structure rather than deleting it.","The printed differentiable-robotics examples are PyRobot and Drake. This is a source-specific list, not an endorsement or current product comparison.","Meta-learning is associated with fast adaptation to new robot morphologies, not eliminating all data or making geometry identical.","A derivative used in optimization may be Jacobian-like without being the robot's particular geometric velocity Jacobian; dimensions, variables and physical meaning matter."],
323:["Setting qdot to the jth input unit vector selects column j, so it is the task response to unit rate of that joint with the other rates zero.","Matrix multiplication forms the weighted column sum: 2c1+0c2-1c3=2c1-c3.","An ordinary determinant is defined for square matrices. Rectangular task maps require rank analysis relative to their achievable regular rank.","The summary associates force control with J transpose.","Substitute v=J qdot into virtual power: tau transpose qdot=f transpose J qdot=(J transpose f) transpose qdot. Equality for all rates implies tau=J transpose f.","J transpose=[[1,0],[2,1]], so multiplying (3,4) gives (3,10)."]}
answers=[]
for q in b['questions']:
 page=int(q['id'].split('-P')[1][:4]);idx=int(q['id'].rsplit('Q',1)[1])-1
 assert idx<len(reasons[page]);ans=['o1','o2'] if q['id']=='W02-L09-P0322-Q02' else ['o1']
 answers.append({'questionId':q['id'],'questionVersion':q['version'],'blindItemSha256':hashlib.sha256(json.dumps(q,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()).hexdigest(),'independentAnswerOptionIds':ans,'reasoning':reasons[page][idx],'reviewedSlideIds':[c['slideId'] for c in q['citations']]})
assert len(answers)==sum(map(len,reasons.values()))==102
out={'reviewerId':'build_offline_study_interface-L09-independent','frozenAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'complete':True,'solvedBeforeAnswerSeen':True,'keyedBatchOpened':False,'sourcePacketPath':b['sourcePacketPath'],'sourcePacketSha256':b['sourcePacketSha256'],'reviewCopyPath':str(P.relative_to(ROOT)),'reviewCopySha256':hashlib.sha256(P.read_bytes()).hexdigest(),'sourcePagesInspected':list(range(296,326)),'sourceInspectionMethod':'All 30 actual 1800x1013 page previews read at readable scale, including equations, code, diagrams, table rows and small-angle geometry, alongside per-page extracted text. Source claims distinguished from generated derivations. Citation evidenceText was removed before solving.','answers':answers,'sourceNotes':['Page 321 source extraction contains combining theta overdot, but the preview poorly displays the dot. The rate-times-time update is supported by its encoded text and RMRC context; do not silently infer a different units-inconsistent update.','Page 309 finite chord versus arc equality needs a small-angle limit qualification. Pages 316/319/321/322/323 contain generalized statements that need dimensional, rank, model-accuracy or safety qualifiers.']}
p=ROOT/'audits/blind-answers-W02-L09-independent.json';assert not p.exists();p.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print('Frozen',len(answers),'blind answers at',out['frozenAt'])
